using CheckoutPricing.Application;
using CheckoutPricing.Domain;
using static CheckoutPricing.UnitTest.Features.Euros;

namespace CheckoutPricing.UnitTest.Features.ShippingFee;

public sealed class CalculateShippingFeeAcceptanceTests
{
    // Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData(49.99, LoyaltyTier.Bronze, 4.90)]
    [InlineData(50.00, LoyaltyTier.Bronze, 0.00)]
    [InlineData(49.99, LoyaltyTier.Silver, 4.90)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(double total, LoyaltyTier tier, double fee)
    {
        var result = new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Cents(total), tier));

        Assert.Equal(Cents(fee), result);
    }

    // Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumMembersNeverPayStandardShipping(LoyaltyTier tier)
    {
        var result = new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Cents(10.00), tier));

        Assert.Equal(Cents(0.00), result);
    }

    // Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData(100.00, LoyaltyTier.Bronze, 9.90)]
    [InlineData(10.00, LoyaltyTier.Gold, 9.90)]
    [InlineData(10.00, LoyaltyTier.Platinum, 0.00)]
    public void S13_ExpressShippingCostsNinePointNinetyFreeForPlatinumOnly(double total, LoyaltyTier tier, double fee)
    {
        var result = new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Cents(total), tier, Express: true));

        Assert.Equal(Cents(fee), result);
    }
}
E
