+using CheckoutPricing.Application;
+using CheckoutPricing.Domain;
+using static CheckoutPricing.UnitTest.Features.Euros;
+
+namespace CheckoutPricing.UnitTest.Features.CheckoutQuote;
+
+public sealed class QuoteCheckoutAcceptanceTests
+{
+    // The checkout quote adds shipping to the payable total
+    [Theory]
+    [InlineData(100.00, LoyaltyTier.Silver, "WELCOME5", "standard", 85.00, 0.00, 85.00)]
+    [InlineData(50.00, LoyaltyTier.Bronze, "none", "standard", 47.50, 4.90, 52.40)]
+    [InlineData(200.00, LoyaltyTier.Platinum, "SUMMER10", "express", 165.00, 0.00, 165.00)]
+    [InlineData(20.00, LoyaltyTier.Gold, "none", "express", 20.00, 9.90, 29.90)]
+    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
+        double subtotal, LoyaltyTier tier, string code, string shipping, double payable, double fee, double total)
+    {
+        var quote = new QuoteCheckout().Handle(
+            new QuoteCheckoutQuery(Cents(subtotal), tier, Code(code), shipping == "express"));
+
+        Assert.Equal(Cents(payable), quote.PayableCents);
+        Assert.Equal(Cents(fee), quote.ShippingCents);
+        Assert.Equal(Cents(total), quote.TotalCents);
+    }
+}

